import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.DQhM5RF8.js";const m=JSON.parse('{"title":"Economy, Loot & Fishing Probabilities","description":"","frontmatter":{},"headers":[],"relativePath":"stats/economy.md","filePath":"stats/economy.md"}'),i={name:"stats/economy.md"};function l(s,t,r,d,c,g){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="economy-loot-fishing-probabilities" tabindex="-1">Economy, Loot &amp; Fishing Probabilities <a class="header-anchor" href="#economy-loot-fishing-probabilities" aria-label="Permalink to &quot;Economy, Loot &amp; Fishing Probabilities&quot;">​</a></h1><p>Statistical breakdown of LlamaCraft&#39;s dynamic fishing distribution, Sealed Tome drop rates, and player market economy.</p><hr><h2 id="sealed-tome-drop-rates-custom-enchants-via-fishing" tabindex="-1">Sealed Tome Drop Rates (Custom Enchants via Fishing) <a class="header-anchor" href="#sealed-tome-drop-rates-custom-enchants-via-fishing" aria-label="Permalink to &quot;Sealed Tome Drop Rates (Custom Enchants via Fishing)&quot;">​</a></h2><p>Custom enchantments on LlamaCraft are discovered dynamically by fishing up <strong>Sealed Tomes</strong> via EvenMoreFish integration. Players right-click a tome to unlock a random enchantment from that rarity tier.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Tome Tier</th><th style="text-align:left;">Weight</th><th style="text-align:left;">Catch Probability</th><th style="text-align:left;">Avg Catches Per Tome</th><th style="text-align:left;">Global Broadcast</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enchanted Tome (Uncommon)</strong></td><td style="text-align:left;"><code>60</code></td><td style="text-align:left;"><code>~4.66%</code></td><td style="text-align:left;">1 in every 21.5 catches</td><td style="text-align:left;">No</td></tr><tr><td style="text-align:left;"><strong>Arcane Tome (Rare)</strong></td><td style="text-align:left;"><code>30</code></td><td style="text-align:left;"><code>~2.33%</code></td><td style="text-align:left;">1 in every 43.0 catches</td><td style="text-align:left;">No</td></tr><tr><td style="text-align:left;"><strong>Relic Tome (Mythic)</strong></td><td style="text-align:left;"><code>8</code></td><td style="text-align:left;"><code>~0.62%</code></td><td style="text-align:left;">1 in every 161.3 catches</td><td style="text-align:left;"><strong>Yes (Global Alert)</strong></td></tr></tbody></table><h3 id="fishing-pool-baseline-weights" tabindex="-1">Fishing Pool Baseline Weights <a class="header-anchor" href="#fishing-pool-baseline-weights" aria-label="Permalink to &quot;Fishing Pool Baseline Weights&quot;">​</a></h3><p>Fish weights are calibrated on a 10x scale to prevent inventory flooding while maintaining rewarding progression:</p><ul><li><strong>Common Tier</strong>: Weight <code>1,000</code></li><li><strong>Rare Tier</strong>: Weight <code>100</code></li><li><strong>Junk Tier</strong>: Weight <code>50</code></li><li><strong>Epic Tier</strong>: Weight <code>30</code></li><li><strong>Legendary Tier</strong>: Weight <code>10</code></li></ul><hr><h2 id="currency-scaling-denominations" tabindex="-1">Currency Scaling &amp; Denominations <a class="header-anchor" href="#currency-scaling-denominations" aria-label="Permalink to &quot;Currency Scaling &amp; Denominations&quot;">​</a></h2><p>The LlamaCraft economy scales dynamically across four primary denomination tiers with built-in shorthand formatting:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Notation</th><th style="text-align:left;">Suffix</th><th style="text-align:left;">Value Range</th><th style="text-align:left;">Common Sources</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Coins (K)</strong></td><td style="text-align:left;"><code>k</code></td><td style="text-align:left;"><code>$1,000 - $999,999</code></td><td style="text-align:left;">Starter quests, basic crop farming, mob bounty</td></tr><tr><td style="text-align:left;"><strong>Millions (M)</strong></td><td style="text-align:left;"><code>m</code></td><td style="text-align:left;"><code>$1,000,000 - $999,999,999</code></td><td style="text-align:left;">Rare ore mining, enchanted gear trades, fish tournaments</td></tr><tr><td style="text-align:left;"><strong>Billions (B)</strong></td><td style="text-align:left;"><code>b</code></td><td style="text-align:left;"><code>$1,000,000,000 - $999,999,999,999</code></td><td style="text-align:left;">Clan territory monopolies, automated spawner farms</td></tr><tr><td style="text-align:left;"><strong>Trillions (T)</strong></td><td style="text-align:left;"><code>t</code></td><td style="text-align:left;"><code>$1,000,000,000,000+</code></td><td style="text-align:left;">Top clan treasuries and server market titans</td></tr></tbody></table><hr><h2 id="market-tax-anti-inflation-rules" tabindex="-1">Market Tax &amp; Anti-Inflation Rules <a class="header-anchor" href="#market-tax-anti-inflation-rules" aria-label="Permalink to &quot;Market Tax &amp; Anti-Inflation Rules&quot;">​</a></h2><ul><li><strong>Player-to-Player <code>/pay</code></strong>: Zero transaction tax for personal transfers between friends.</li><li><strong>Chest Shop Listings</strong>: Fixed 2% transaction fee deposited into the community server chest to curb hyperinflation.</li><li><strong>Auction House (<code>/ah</code>)</strong>: 48-hour expiration on unsold goods with automatic inventory reclamation.</li></ul>',16)])])}const y=e(i,[["render",l]]);export{m as __pageData,y as default};
